-- Run this entire file once in Supabase SQL Editor.
create table if not exists public.app_settings (id integer primary key default 1 check(id=1), supervisor_email text not null);
insert into public.app_settings(id,supervisor_email) values(1,'brandon@dangelo-brothers.com') on conflict(id) do update set supervisor_email=excluded.supervisor_email;
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade,email text not null,role text not null default 'viewer' check(role in('supervisor','viewer')));
create table if not exists public.crews (id bigint generated by default as identity primary key,name text not null unique,sort_order integer not null);
create table if not exists public.jobs (id bigint generated by default as identity primary key,job_name text not null,address text,miss_dig_number text,job_number text,notes text,customer text,customer_phone text,job_type text,permit_number text,inspector text,priority text not null default 'non_emergency' check(priority in('emergency','pressing','non_emergency')),start_date date,end_date date,crew_id bigint references public.crews(id) on delete set null,created_at timestamptz not null default now(),constraint dates_together check((start_date is null and end_date is null)or(start_date is not null and end_date is not null and end_date>=start_date)));
insert into public.crews(name,sort_order) values('Chad',1),('Nick',2),('Bernie',3),('Chava',4),('Gasper',5),('Pablo',6),('Jon',7),('Remy',8),('Sammy',9),('Tony Ha',10) on conflict(name) do update set sort_order=excluded.sort_order;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ declare supervisor text; begin select supervisor_email into supervisor from public.app_settings where id=1; insert into public.profiles(id,email,role) values(new.id,coalesce(new.email,''),case when lower(coalesce(new.email,''))=lower(supervisor) then 'supervisor' else 'viewer' end) on conflict(id) do nothing; return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
insert into public.profiles(id,email,role) select u.id,coalesce(u.email,''),case when lower(coalesce(u.email,''))=lower((select supervisor_email from public.app_settings where id=1)) then 'supervisor' else 'viewer' end from auth.users u on conflict(id) do update set email=excluded.email,role=excluded.role;
create or replace function public.is_supervisor() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='supervisor') $$;
alter table public.app_settings enable row level security; alter table public.profiles enable row level security; alter table public.crews enable row level security; alter table public.jobs enable row level security;
drop policy if exists "profiles own read" on public.profiles; create policy "profiles own read" on public.profiles for select to authenticated using(id=auth.uid());
drop policy if exists "crews authenticated read" on public.crews; create policy "crews authenticated read" on public.crews for select to authenticated using(true);
drop policy if exists "jobs authenticated read" on public.jobs; create policy "jobs authenticated read" on public.jobs for select to authenticated using(true);
drop policy if exists "jobs supervisor insert" on public.jobs; create policy "jobs supervisor insert" on public.jobs for insert to authenticated with check(public.is_supervisor());
drop policy if exists "jobs supervisor update" on public.jobs; create policy "jobs supervisor update" on public.jobs for update to authenticated using(public.is_supervisor()) with check(public.is_supervisor());
drop policy if exists "jobs supervisor delete" on public.jobs; create policy "jobs supervisor delete" on public.jobs for delete to authenticated using(public.is_supervisor());
